from __future__ import annotations

import base64
import gzip
import hashlib
import py_compile
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
BUILD_FILE = ROOT / "build.py"
EXPECTED_SHA256 = "65f255ae4f24de2a1d141bc810e66133c5973f0ae8667095a06b47dc0d5572ef"
PAYLOAD = """"""


def main() -> None:
    content = gzip.decompress(base64.b64decode(PAYLOAD))
    digest = hashlib.sha256(content).hexdigest()
    if digest != EXPECTED_SHA256:
        raise RuntimeError(f"build.py payload hash mismatch: {digest}")
    BUILD_FILE.write_bytes(content)
    py_compile.compile(str(BUILD_FILE), doraise=True)
    print(f"[OK] Wrote deterministic build.py: {digest}")


if __name__ == "__main__":
    main()
